INSERT INTO major_info (code, title, careers, result_reason, explore_text, related_courses) VALUES
('cs', 'Computer Science', 'You may enjoy roles such as computer scientist, systems analyst, research developer, or algorithm-focused engineer.', 'Your answers show strong interest in logical reasoning, complex technical problem-solving, and computational thinking.', 'Computer Science focuses on algorithms, programming concepts, systems thinking, and solving technical problems at a deeper level.', '[{"name": "Artificial Intelligence", "url": ""}, {"name": "Mathematics", "url": ""}, {"name": "Computational Physics", "url": ""}]'),
('se', 'Software Development', 'You may enjoy roles such as software developer, web developer, mobile app developer, or application engineer.', 'Your answers show strong interest in building applications, designing practical solutions, and creating digital products for users.', 'Software Development focuses on designing, building, testing, and improving applications, websites, and digital systems.', '[{"name": "UX/UI Interaction Design", "url": ""}, {"name": "Games Development", "url": ""}, {"name": "Digital Media", "url": ""}]'),
('cyber', 'Cyber Security', 'You may enjoy roles such as cyber security analyst, security consultant, penetration tester, or security operations specialist.', 'Your answers show strong interest in protecting systems, managing risks, and identifying digital threats and vulnerabilities.', 'Cyber Security focuses on defending systems, networks, and data against cyber threats and improving digital safety.', '[{"name": "Criminology", "url": ""}, {"name": "Digital Forensics", "url": ""}, {"name": "Network Engineering", "url": ""}]'),
('ds', 'Data Science', 'You may enjoy roles such as data analyst, data specialist, business intelligence analyst, or insight-driven technical professional.', 'Your answers show strong interest in patterns, data interpretation, and using information to support understanding and decisions.', 'Data Science focuses on analysing data, finding trends, visualising results, and supporting data-driven decision-making.', '[{"name": "Data Analytics", "url": ""}, {"name": "Statistics", "url": ""}, {"name": "Financial Technology", "url": ""}]')
